import { addLog, ErrorLog, InfoLog, SuccessLog } from '@mintlify/previewing';
import { Box, Text } from 'ink';

import type { Report } from './report.js';
import type { Diagnostic } from './types.js';

const preview = (value: string) => {
  const text = JSON.stringify(value);
  return text.length > 60 ? `${text.slice(0, 57)}..."` : text;
};

const location = ({ line, column }: Pick<Diagnostic, 'line' | 'column'>) =>
  line ? `${line}${column ? `:${column}` : ''}` : '';

const DiagnosticLine = ({ diagnostic }: { diagnostic: Diagnostic }) => {
  const at = location(diagnostic);
  return (
    <Text>
      {'  '}
      {diagnostic.severity === 'error' ? (
        <Text color="red">✗</Text>
      ) : (
        <Text color="yellow">!</Text>
      )}{' '}
      {at && <Text dimColor>{at} </Text>}
      <Text dimColor>{diagnostic.rule}</Text> {diagnostic.message}
      {diagnostic.fix && <Text dimColor> (fixable)</Text>}
    </Text>
  );
};

const plural = (count: number, word: string) => `${count} ${word}${count === 1 ? '' : 's'}`;

export const logReport = (report: Report) => {
  for (const change of report.fixed ?? []) {
    addLog(
      <SuccessLog
        message={`fixed ${change.file}${change.line ? `:${change.line}` : ''} ${change.rule}: ${preview(change.before)} → ${preview(change.after)}`}
      />
    );
  }

  const byFile = new Map<string, Diagnostic[]>();
  for (const diagnostic of report.diagnostics) {
    byFile.get(diagnostic.file)?.push(diagnostic) ?? byFile.set(diagnostic.file, [diagnostic]);
  }
  for (const [file, diagnostics] of byFile) {
    addLog(
      <Box flexDirection="column">
        <Text bold>{file}</Text>
        {diagnostics.map((diagnostic, index) => (
          <DiagnosticLine key={index} diagnostic={diagnostic} />
        ))}
      </Box>
    );
  }

  const fixable = report.diagnostics.filter(({ fix }) => fix).length;
  if (fixable > 0 && !report.fixed) {
    addLog(<InfoLog message={`\`--fix\` would fix ${plural(fixable, 'issue')}.`} />);
  }

  const { build } = report;
  if (build.ran && build.passed) addLog(<SuccessLog message="build passed" />);
  else if (build.ran && report.passed)
    addLog(<InfoLog message="build failed only on disabled rules" />);
  else if (build.ran) addLog(<ErrorLog message="build failed" />);
  else if (build.reason === 'errors found')
    addLog(<InfoLog message="build skipped until the errors above are fixed" />);

  const { errors, warnings } = report.summary;
  const warned = plural(warnings, 'warning');
  const passed = warnings > 0 ? `passed with ${warned}` : 'validation passed';
  const failed = `${plural(errors, 'error')}${warnings > 0 ? `, ${warned}` : ''}`;
  addLog(report.passed ? <SuccessLog message={passed} /> : <ErrorLog message={failed} />);
};
